const e="missouri-district-childrens-talentfest",d=2019,t="Read from the whole 2019 Children's TalentFest information and application (letter, age categories, eight category rules, general guidelines, application form). Placed: general rules, eligibility, registration steps, fees, date and time, judging, per-category rules, age categories and group rules. Edition facts are Variables: date, times, venue, deadline, fees, check payee, online form link, mailing address and the director's contact. The source does not print: marks per judging area, points, ranks, grades, prizes beyond certificates, a street address for the venue, or any news. The 2019 edition is the newest printed; its dates and venue are past-edition starting suggestions. The document prints a private home street address for mailing; it is not copied (the Variable keeps only the city), and the organiser fills in the current address. Primary and Intermediate are printed as school grades, so the template ages 6-9 and 10-12 are placeholders. Performance Arts is headed 'Dramatic Arts' in its own rules list. The director's e-mail and phone are printed as the event contact.",n={Title:"Rules & Criteria",Subtitle:"Missouri District Children's TalentFest. Read these rules before you register.",NoticeTitle:"Please Read Before Registering",Notice:"The TalentFest is on {{EventDate}} at {{Venue}}. Registration and check-in start at {{CheckInTime}}. All entries and fees must be received by {{RegistrationDeadline}}.",Notes:["The opening session starts at {{OpeningTime}} and judging starts at {{JudgingTime}}.","Children are judged on their own performance, not against another child."],Sections:[{Key:"general",Title:"General Rules",Items:["TalentFest is for children from preschool to 6th grade. It is not only for music, art or drama: every child should think about the talents God has given them.","Each talent is scored on a scale of 1 to 4, where 1 is the best, in areas that fit that category.","Different scoring sheets are used for the different age categories so that the judging is age appropriate.","One area judged in every category is compliance to rules. Children and parents must know the rules of each category to avoid being marked down.","Some rules changed in 2019. Read the rules for each category again each year.","For music entries, piano or CD accompaniment may be used. CDs with or without background vocals are allowed. Cassette tapes are not allowed.","A one-hour lunch break is held if it is needed. It depends on the number of entries. Bring a lunch or use the restaurants nearby.","A child who sent an application but cannot attend must tell the TalentFest director as soon as possible.","All judges were chosen for their expertise in the category they judge. Their decisions are final."]},{Key:"eligibility",Title:"Eligibility",Items:["The child must attend a church of the Missouri District of the Church of the Nazarene.","There are three age categories: Preschool (ages 4-5), Primary (kindergarten through 3rd grade) and Intermediate (4th through 6th grade).","A group of two or more children is placed in the age category of the oldest child in the group.","A child may enter up to 3 events in total.","A child may have as many as two separate entries in any one category, but no more than 3 entries in total for the day.","A large ensemble is a group of 6 or more.","Preschool entries in Bible Memorization need at least 1 verse memorized.","Primary entries in Creative Writing need at least half a page typed. Intermediate entries need at least 1 page typed."]},{Key:"registration",Title:"How to Register",Items:["Register online. The organiser strongly encourages online registration: {{OnlineRegistration}}.","Paper applications are also accepted. Each child completes one form, except choirs, which use one form for the choir.","A child can register online alone, or give the paper form to the church children's director, who registers the child.","Online registration lets you change or add entries until {{ChangeDeadline}}.","All entries must be received, online or by mail, by {{RegistrationDeadline}}. This leaves time to print a certificate for every entry.","Send only one packet of paper applications and one check per church.","Mail the checks and all paper forms to {{MailingAddress}}.","The paper form asks for the child's name, age, grade, address, phone, home church, children's director's name and phone, the events entered with an entry title for each, and the names and ages of others in a group.","Choirs also give the choir name, director name, title of the selection and number of members taking part. It is not necessary to list every choir member.","The paper form is signed by the applicant and by the local talent director.","All registrations and fees must be received by the deadline.","Children with entries in all categories must be checked in by {{JudgingTime}}.","Creative Writing entries are submitted in advance with the application. If you register online, send the writing by e-mail to {{ContactPerson}}.","Technology entries must be sent electronically in advance. They may be sent separately from the registration, but must arrive by {{RegistrationDeadline}}."]},{Key:"fees",Title:"Fees and Payment",Items:["The fee is {{EntryFee}}.","Fees must be mailed in advance of the event. Write the check to {{CheckPayableTo}}, with the words Children's Talent on the memo line.","Send one check per church."]},{Key:"dates",Title:"Date and Time",Items:["The TalentFest is on {{EventDate}}.","Registration and check-in start at {{CheckInTime}}. The opening session starts at {{OpeningTime}}. Judging starts at {{JudgingTime}}."]},{Key:"venue",Title:"Location",Items:["The TalentFest is held at {{Venue}}."]},{Key:"judging",Title:"Judging",Items:["A set of qualified judges in each category looks at each child's talent and scores it from 1 to 4, with 1 the best.","The judges' decisions are final."]},{Key:"prizes",Title:"Certificates",Items:["A certificate is printed for each entry."]}],Documents:[{Title:"2019 TalentFest Information and Application (PDF)",Url:"https://monaz.org/wp-content/uploads/2019/01/2019-TalentFest-Information-and-Application.pdf"}]},i=[{ParticipantType:"Team",Source:"Age Categories and application",Sections:{About:null,TimeAndFormat:null,Rules:["A group of two or more is placed in the age category of the oldest child in the group.","A large ensemble or choir is a group of 6 or more.","For a group, list the names and ages of the others in the group on the form.","Choirs give the choir name, director, title and number of members."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## Rules
- A group of two or more is placed in the age category of the oldest child in the group.
- A large ensemble or choir is a group of 6 or more.
- For a group, list the names and ages of the others in the group on the form.
- Choirs give the choir name, director, title and number of members.`}],a=[{AgeGroup:"Preschool",Source:"Age Categories",Sections:{About:null,TimeAndFormat:null,Rules:["Preschool is for ages 4-5."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:["Coloring is a Visual Arts entry for Preschool only."]},Markdown:`## Rules
- Preschool is for ages 4-5.

## Notes for participants
- Coloring is a Visual Arts entry for Preschool only.`},{AgeGroup:"Primary",Source:"Age Categories",Sections:{About:null,TimeAndFormat:null,Rules:["Primary is for kindergarten through 3rd grade."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:["The age band 6-9 in this template is a placeholder for those grades."]},Markdown:`## Rules
- Primary is for kindergarten through 3rd grade.

## Notes for participants
- The age band 6-9 in this template is a placeholder for those grades.`},{AgeGroup:"Intermediate",Source:"Age Categories",Sections:{About:null,TimeAndFormat:null,Rules:["Intermediate is for 4th through 6th grade."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:["The age band 10-12 in this template is a placeholder for those grades."]},Markdown:`## Rules
- Intermediate is for 4th through 6th grade.

## Notes for participants
- The age band 10-12 in this template is a placeholder for those grades.`}],o=[{Title:"Vocal Music",Source:"Talent Categories and Rules - Vocal Music",Sections:{About:["Vocal solos, duets, trios, quartets and choirs."],TimeAndFormat:["Selection must be no longer than 4 minutes."],Rules:["Two copies of the music must be given to the judges before the performance.","Selection must be Christian, patriotic or classical.","Handwritten lyrics are not accepted.","Selection must be memorized."],Allowed:null,NotAllowed:null,Judging:["Pitch and harmony, tone quality, rhythm, dynamics, diction, effect, stage presence and technical difficulty."],Points:null,Notes:null},Markdown:`## About this competition
- Vocal solos, duets, trios, quartets and choirs.

## Time and format
- Selection must be no longer than 4 minutes.

## Rules
- Two copies of the music must be given to the judges before the performance.
- Selection must be Christian, patriotic or classical.
- Handwritten lyrics are not accepted.
- Selection must be memorized.

## Judging
- Pitch and harmony, tone quality, rhythm, dynamics, diction, effect, stage presence and technical difficulty.`},{Title:"Instrumental Music",Source:"Talent Categories and Rules - Instrumental Music",Sections:{About:["Instrumental solos, duets, trios, quartets and choirs."],TimeAndFormat:["Selection must be no longer than 4 minutes."],Rules:["Two copies of the music must be given to the judges before the performance.","Selection must be Christian, patriotic or classical.","Selection does not need to be memorized."],Allowed:null,NotAllowed:null,Judging:["Pitch and harmony, tone quality, dynamics, articulation, effect, stage presence and technical difficulty."],Points:null,Notes:null},Markdown:`## About this competition
- Instrumental solos, duets, trios, quartets and choirs.

## Time and format
- Selection must be no longer than 4 minutes.

## Rules
- Two copies of the music must be given to the judges before the performance.
- Selection must be Christian, patriotic or classical.
- Selection does not need to be memorized.

## Judging
- Pitch and harmony, tone quality, dynamics, articulation, effect, stage presence and technical difficulty.`},{Title:"Performance Arts",Source:"Talent Categories and Rules - Performance Arts (headed Dramatic Arts in its rules list)",Sections:{About:["Puppetry, monologues, skits, ventriloquist acts, sports demonstrations, dancing, teaching of a Sunday School lesson and similar acts."],TimeAndFormat:["Performance must be no longer than 8 minutes."],Rules:["Two copies of the script, if there is one, must be given to the judges before the performance. Handwritten entries are not accepted.","Selection must be Christian or patriotic.","Selection must be memorized."],Allowed:null,NotAllowed:null,Judging:["Expression, diction, effect, stage presence, execution and technical difficulty."],Points:null,Notes:null},Markdown:`## About this competition
- Puppetry, monologues, skits, ventriloquist acts, sports demonstrations, dancing, teaching of a Sunday School lesson and similar acts.

## Time and format
- Performance must be no longer than 8 minutes.

## Rules
- Two copies of the script, if there is one, must be given to the judges before the performance. Handwritten entries are not accepted.
- Selection must be Christian or patriotic.
- Selection must be memorized.

## Judging
- Expression, diction, effect, stage presence, execution and technical difficulty.`},{Title:"Visual Arts",Source:"Talent Categories and Rules - Visual Arts",Sections:{About:["Photography, needlework, drawings, paintings, three-dimensional projects and coloring (Preschool only)."],TimeAndFormat:null,Rules:["The theme and the child's name card must be next to the project. Cards are given out at registration.","The entry must have a Christian, nature or patriotic theme."],Allowed:null,NotAllowed:null,Judging:["Line, shape, form, color, value, texture, space, balance, design, creativity, technique and neatness."],Points:null,Notes:null},Markdown:`## About this competition
- Photography, needlework, drawings, paintings, three-dimensional projects and coloring (Preschool only).

## Rules
- The theme and the child's name card must be next to the project. Cards are given out at registration.
- The entry must have a Christian, nature or patriotic theme.

## Judging
- Line, shape, form, color, value, texture, space, balance, design, creativity, technique and neatness.`},{Title:"Culinary Arts",Source:"Talent Categories and Rules - Culinary Arts",Sections:{About:["Cooking appetizers, main dishes, vegetables, desserts and other dishes."],TimeAndFormat:null,Rules:["The name of the dish and the child's name card must be next to the dish. Cards are given out at registration.","Dishes must be prepared before the event. A microwave or oven is available for reheating.","Every entry must have a display that shows each step of the culinary project, for example photos taken while cooking or the recipe. Handwritten recipes are not accepted."],Allowed:null,NotAllowed:null,Judging:["Presentation, creativity and taste."],Points:null,Notes:null},Markdown:`## About this competition
- Cooking appetizers, main dishes, vegetables, desserts and other dishes.

## Rules
- The name of the dish and the child's name card must be next to the dish. Cards are given out at registration.
- Dishes must be prepared before the event. A microwave or oven is available for reheating.
- Every entry must have a display that shows each step of the culinary project, for example photos taken while cooking or the recipe. Handwritten recipes are not accepted.

## Judging
- Presentation, creativity and taste.`},{Title:"Bible Memorization",Source:"Talent Categories and Rules - Bible Memorization",Sections:{About:["Reciting memorized Bible verses."],TimeAndFormat:null,Rules:["Preschool must have at least 1 verse memorized, Primary at least 5 verses and Intermediate at least 10 verses.","Two copies of the full passage must be given to the judges before the recitation."],Allowed:null,NotAllowed:null,Judging:["Memorization, expression, diction, stage presence and difficulty."],Points:null,Notes:null},Markdown:`## About this competition
- Reciting memorized Bible verses.

## Rules
- Preschool must have at least 1 verse memorized, Primary at least 5 verses and Intermediate at least 10 verses.
- Two copies of the full passage must be given to the judges before the recitation.

## Judging
- Memorization, expression, diction, stage presence and difficulty.`},{Title:"Creative Writing",Source:"Talent Categories and Rules - Creative Writing",Sections:{About:["Short stories and essays."],TimeAndFormat:null,Rules:["Primary must have at least half a page typed. Intermediate must have at least 1 page typed.","Entries must be submitted in advance with the application, by {{RegistrationDeadline}}."],Allowed:null,NotAllowed:null,Judging:["Ideas and content, word choice, conventions, organization and sentence fluency."],Points:null,Notes:null},Markdown:`## About this competition
- Short stories and essays.

## Rules
- Primary must have at least half a page typed. Intermediate must have at least 1 page typed.
- Entries must be submitted in advance with the application, by {{RegistrationDeadline}}.

## Judging
- Ideas and content, word choice, conventions, organization and sentence fluency.`},{Title:"Technology",Source:"Talent Categories and Rules - Technology",Sections:{About:["Any entry in this category must be submitted electronically in advance."],TimeAndFormat:["A video can be no longer than 3 minutes."],Rules:["The entry must be Christian or patriotic/nature.","Entries may be sent separately from the registration, but must arrive electronically by {{RegistrationDeadline}}."],Allowed:null,NotAllowed:null,Judging:null,Points:null,Notes:null},Markdown:`## About this competition
- Any entry in this category must be submitted electronically in advance.

## Time and format
- A video can be no longer than 3 minutes.

## Rules
- The entry must be Christian or patriotic/nature.
- Entries may be sent separately from the registration, but must arrive electronically by {{RegistrationDeadline}}.`}],r=[],s=[{Key:"EventDate",Kind:"date",Label:"Event date",Value:"2019-02-23",Source:"Letter, p.1"},{Key:"CheckInTime",Kind:"time",Label:"Registration and check-in start",Value:"9:30 a.m.",Source:"Letter, p.1"},{Key:"OpeningTime",Kind:"time",Label:"Opening session",Value:"10:00 a.m.",Source:"Letter, p.1"},{Key:"JudgingTime",Kind:"time",Label:"Judging starts and check-in closes",Value:"10:30 a.m.",Source:"Letter p.1 and General Guidelines 5"},{Key:"RegistrationDeadline",Kind:"date",Label:"Last date to register and send fees",Value:"2019-02-15",Source:"Letter, p.1"},{Key:"ChangeDeadline",Kind:"date",Label:"Last date to change online entries",Value:"2019-02-15",Source:"Letter, p.1"},{Key:"Venue",Kind:"address",Label:"Event venue",Value:{Name:"StL Gateway Church of the Nazarene",Address:"",City:"",MapUrl:"",Directions:""},Source:"Letter, p.1"},{Key:"EntryFee",Kind:"fee",Label:"Entry fee",Value:"$4 per individual per category and $10 per choir or large ensemble (6 or more)",Source:"Letter p.1 and Application"},{Key:"CheckPayableTo",Kind:"text",Label:"Check payable to",Value:"Missouri District Church of the Nazarene",Source:"Letter p.1 and Application"},{Key:"OnlineRegistration",Kind:"link",Label:"Online registration form",Value:"https://goo.gl/forms/i261PG9GJhRBaPdD3",Source:"Application"},{Key:"MailingAddress",Kind:"address",Label:"Mail checks and paper forms to",Value:{Name:"Children's TalentFest director",Address:"Church-district mailing address as printed in the application",City:"Florissant, MO",MapUrl:"",Directions:""},Source:"Letter p.1 and Application"},{Key:"ContactPerson",Kind:"contact",Label:"Contact for questions and writing entries",Value:{Name:"Steven Baker",Role:"Children's TalentFest director",Phone:"314-374-4566",WhatsApp:"",Email:"sbaker2480@hotmail.com"},Source:"Letter, p.1"}],l=[{Claim:"Rules, eligibility, registration steps, fees, dates and category rules for the Children's TalentFest.",SourceType:"Primary - the event's own rules document",Source:"Missouri District Church of the Nazarene - Children's TalentFest 2019 Information and Application",Url:"https://monaz.org/wp-content/uploads/2019/01/2019-TalentFest-Information-and-Application.pdf"}],c={TemplateKey:e,Year:2019,Note:t,Page:n,ParticipantTypes:i,AgeGroups:a,Competitions:o,CompetitionAgeGroups:r,Variables:s,Evidence:l};export{a as AgeGroups,r as CompetitionAgeGroups,o as Competitions,l as Evidence,t as Note,n as Page,i as ParticipantTypes,e as TemplateKey,s as Variables,d as Year,c as default};
